fn fibonacci(n: usize) -> Vec<i32> {
    let mut result = Vec::with_capacity(n);
    
    if n >= 1 {
        result.push(0);
    }
    if n >= 2 {
        result.push(1);
    }
    
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}